using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Racer;using Object=UnityEngine.Object;
public static class AlignReverseLipMetadata {public static string Main(){EditorApplication.delayCall+=()=>{try{EditorSceneManager.OpenScene("Assets/Scenes/DansBackyardReverse.unity");Physics.SyncTransforms();var r=Object.FindAnyObjectByType<RaceDirector>();var c=r.GetComponent<BackyardForwardCourse>();var old=c.flightStarts[2];var best=old;best.y=-100;for(float x=387.5f;x<=389;x+=.02f){var p=new Vector3(x,0,-3.1f+(x-389)*.2f);p.y=Racer.Editor.BackyardReverseAuthoring.Ground(p);if(p.y>best.y)best=p;}best-=c.flightDirections[2]*.06f;best.y=Racer.Editor.BackyardReverseAuthoring.Ground(best);c.flightStarts[2]=best;r.road.Initialize();c.launchStations[2]=r.road.Project(best,out _);Object.FindAnyObjectByType<ForestLayout>().jumpStarts=c.launchStations;EditorUtility.SetDirty(c);EditorSceneManager.MarkSceneDirty(UnityEngine.SceneManagement.SceneManager.GetActiveScene());EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());AssetDatabase.SaveAssets();Racer.Editor.BackyardReverseAuthoring.ExportReverse();var tree=Object.FindObjectsByType<Collider>().First(x=>x.name=="CR014 trunk 04701");float gap=tree.bounds.min.y-Racer.Editor.BackyardReverseAuthoring.Ground(tree.bounds.center);if(Mathf.Abs(gap)>.025f)throw new Exception("Tree support mismatch "+gap);File.WriteAllText("Docs/BackyardReverseCorrections/lip-metadata.txt","Metadata-only correction: "+old+" -> actual supported lip "+best+"; launch station="+c.launchStations[2]+". Tested physical mesh, gate positions, XZ navigation and landing unchanged. Restored tree foot error="+gap+"m.");}catch(Exception e){File.WriteAllText("Docs/BackyardReverseCorrections/lip-metadata-error.txt",e.ToString());}};return "Place flight metadata on actual supported lip, without changing tested geometry";}}
